{"command": "python3 -c "
from rdkit import Chem
smiles = 'COc1ccc(C)n2nc(CCc3nc(-c4ccccc4)nn3CCO)nc12'
mol = Chem.MolFromSmiles(smiles)
if mol:
    print('Valid SMILES')
    print(f'Formula: {Chem.rdMolDescriptors.CalcMolFormula(mol)}')
    print(f'MW: {Chem.rdMolDescriptors.CalcExactMolWt(mol)}')
    # Count heteroatoms
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() in [7, 8]:
            print(f'Atom {atom.GetIdx()}: {atom.GetSymbol()} in ring {atom.IsInRing()}')
else:
    print('Invalid SMILES')
"
